foreach($forbidden in @('minikube start','minikube delete','docker start','docker restart','docker rm','docker volume rm','apply -k','manage-network-delay-proxy','toxic add')){if($runner.Contains($forbidden)){throw "state_postmortem_forbidden_mutation:$forbidden"}}
