$prereg=Get-Content -LiteralPath(Join-Path $PSScriptRoot '..\artifacts\P2-MINIKUBE-STATE-POSTMORTEM-001\ob-minikube-state-postmortem-001-preregistration.md')-Raw
foreach($required in @('ob-minikube-state-postmortem-001','read-only','resolved MINIKUBE_HOME','Profile delete','cluster start','canonical merge','runtime approval')){if(-not$prereg.Contains($required)){throw "state_postmortem_prereg_contract_missing:$required"}}
Write-Output 'minikube_state_postmortem_contract_tests=passed'
